00, '2012:1331183700:1331184300', 600, 'lt_1h' UNION ALL SELECT 1331184300, 1331184900, '2012:1331184300:1331184900', 600, 'lt_1h' UNION ALL SELECT 1331184900, 1331185500, '2012:1331184900:1331185500', 600, 'lt_1h' UNION ALL SELECT 1331185500, 1331186100, '2012:1331185500:1331186100', 600, 'lt_1h' UNION ALL SELECT 1331186100, 1331186700, '2012:1331186100:1331186700', 600, 'lt_1h' UNION ALL SELECT 1331186700, 1331187300, '2012:1331186700:1331187300', 600, 'lt_1h' UNION ALL SELECT 1331187300, 1331187900, '2012:1331187300:1331187900', 600, 'lt_1h' UNION ALL SELECT 1331187900, 1331188500, '2012:1331187900:1331188500', 600, 'lt_1h' UNION ALL SELECT 1331188500, 1331189100, '2012:1331188500:1331189100', 600, 'lt_1h' UNION ALL SELECT 1331189100, 1331189700, '2012:1331189100:1331189700', 600, 'lt_1h' UNION ALL SELECT 1331189700, 1331190300, '2012:1331189700:1331190300', 600, 'lt_1h' UNION ALL SELECT 1331190300, 1331190900, '2012:1331190300:1331190900', 600, 'lt_1h' UNION ALL SELECT 1331190900, 1331191500, '2012:1331190900:1331191500', 600, 'lt_1h' UNION ALL SELECT 1331191500, 1331192100, '2012:1331191500:1331192100', 600, 'lt_1h' UNION ALL SELECT 1331192100, 1331192700, '2012:1331192100:1331192700', 600, 'lt_1h' UNION ALL SELECT 1331192700, 1331193300, '2012:1331192700:1331193300', 600, 'lt_1h' UNION ALL SELECT 1331193300, 1331193900, '2012:1331193300:1331193900', 600, 'lt_1h' UNION ALL SELECT 1331193900, 1331194500, '2012:1331193900:1331194500', 600, 'lt_1h' UNION ALL SELECT 1331194500, 1331195100, '2012:1331194500:1331195100', 600, 'lt_1h' UNION ALL SELECT 1331195100, 1331195700, '2012:1331195100:1331195700', 600, 'lt_1h' UNION ALL SELECT 1331195700, 1331196300, '2012:1331195700:1331196300', 600, 'lt_1h' UNION ALL SELECT 1331196300, 1331196900, '2012:1331196300:1331196900', 600, 'lt_1h' UNION ALL SELECT 1331196900, 1331197500, '2012:1331196900:1331197500', 600, 'lt_1h' UNION ALL SELECT 1331197500, 1331198100, '2012:1331197500:1331198100', 600, 'lt_1h' UNION ALL SELECT 1331198100, 1331198700, '2012:1331198100:1331198700', 600, 'lt_1h' UNION ALL SELECT 1331198700, 1331199300, '2012:1331198700:1331199300', 600, 'lt_1h' UNION ALL SELECT 1331199300, 1331199900, '2012:1331199300:1331199900', 600, 'lt_1h' UNION ALL SELECT 1331199900, 1331200500, '2012:1331199900:1331200500', 600, 'lt_1h' UNION ALL SELECT 1331200500, 1331201100, '2012:1331200500:1331201100', 600, 'lt_1h' UNION ALL SELECT 1331201100, 1331201700, '2012:1331201100:1331201700', 600, 'lt_1h' UNION ALL SELECT 1331201700, 1331202300, '2012:1331201700:1331202300', 600, 'lt_1h' UNION ALL SELECT 1331202300, 1331202900, '2012:1331202300:1331202900', 600, 'lt_1h' UNION ALL SELECT 1331202900, 1331203500, '2012:1331202900:1331203500', 600, 'lt_1h' UNION ALL SELECT 1331203500, 1331204100, '2012:1331203500:1331204100', 600, 'lt_1h' UNION ALL SELECT 1331204100, 1331204700, '2012:1331204100:1331204700', 600, 'lt_1h' UNION ALL SELECT 1331204700, 1331205300, '2012:1331204700:1331205300', 600, 'lt_1h' UNION ALL SELECT 1331205300, 1331205900, '2012:1331205300:1331205900', 600, 'lt_1h'), wh_hits AS (
 SELECT t.gap_id,t.gap_band,t.left_time,t.right_time,a.dateTime ts,
        a.usUnits wh_units,a.`interval` wh_interval,a.outTemp wh_temp,a.outHumidity wh_rh,
        a.rain wh_rain,a.rainRate wh_rainRate,a.windSpeed wh_wind
 FROM targets t JOIN weewx_WH1080.archive a
   ON a.dateTime>t.left_time AND a.dateTime<t.right_time AND MOD(a.dateTime-t.left_time,300)=0
 LEFT JOIN loucka_reconstruction.archive r ON r.dateTime=a.dateTime
 WHERE r.dateTime IS NULL
)
SELECT CAST(SUBSTRING_INDEX(h.gap_id,':',1) AS UNSIGNED) utc_year,h.gap_band,
 CASE WHEN h.ts>=1514764800 AND h.ts<1522540800 THEN 'PROTECTED_Q1_2018_DIAGNOSTIC' ELSE 'NORMAL' END protection_scope,
 COUNT(*) wh1080_rows,SUM(o.dateTime IS NOT NULL) old_weewx_rows,
 SUM(o.dateTime IS NULL) old_weewx_missing,
 SUM(h.wh_units=17) wh_units17,SUM(h.wh_interval=5) wh_interval5,
 SUM(o.usUnits<=>h.wh_units) units_equal,SUM(o.`interval`<=>h.wh_interval) intervals_equal,
 SUM(o.outTemp<=>h.wh_temp) outTemp_equal,SUM(o.outTemp IS NOT NULL AND h.wh_temp IS NOT NULL) outTemp_both_present,
 SUM(o.outTemp IS NOT NULL AND h.wh_temp IS NOT NULL AND o.outTemp<>h.wh_temp) outTemp_conflict,
 SUM(h.wh_temp=0) wh_outTemp_zero,SUM(h.wh_temp IS NULL) wh_outTemp_null,
 SUM(o.outHumidity<=>h.wh_rh) outHumidity_equal,SUM(o.outHumidity IS NOT NULL AND h.wh_rh IS NOT NULL) outHumidity_both_present,
 SUM(o.outHumidity IS NOT NULL AND h.wh_rh IS NOT NULL AND o.outHumidity<>h.wh_rh) outHumidity_conflict,
 SUM(h.wh_rh IS NULL) wh_outHumidity_null,
 SUM(o.rain<=>h.wh_rain) rain_equal,SUM(o.rain IS NOT NULL AND h.wh_rain IS NOT NULL) rain_both_present,
 SUM(o.rain IS NOT NULL AND h.wh_rain IS NOT NULL AND o.rain<>h.wh_rain) rain_conflict,
 SUM(h.wh_rain IS NULL) wh_rain_null,
 SUM(o.rainRate<=>h.wh_rainRate) rainRate_equal,SUM(o.rainRate IS NOT NULL AND h.wh_rainRate IS NOT NULL) rainRate_both_present,
 SUM(o.rainRate IS NOT NULL AND h.wh_rainRate IS NOT NULL AND o.rainRate<>h.wh_rainRate) rainRate_conflict,
 SUM(h.wh_rainRate IS NULL) wh_rainRate_null,
 SUM(o.windSpeed<=>h.wh_wind) windSpeed_equal,SUM(o.windSpeed IS NOT NULL AND h.wh_wind IS NOT NULL) windSpeed_both_present,
 SUM(o.windSpeed IS NOT NULL AND h.wh_wind IS NOT NULL AND o.windSpeed<>h.wh_wind) windSpeed_conflict,
 SUM(h.wh_wind IS NULL) wh_windSpeed_null
FROM wh_hits h LEFT JOIN old_weewx.archive o ON o.dateTime=h.ts
GROUP BY utc_year,h.gap_band,protection_scope
